import sys

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    parent = [x - 1 for x in data[2:]]

    indeg = [0] * n
    children = [[] for _ in range(n)]
    for v, p in enumerate(parent):
        indeg[p] += 1
        children[p].append(v)

    queue = [v for v in range(n) if indeg[v] == 0]
    removed_order = []
    for v in queue:
        removed_order.append(v)
        p = parent[v]
        indeg[p] -= 1
        if indeg[p] == 0:
            queue.append(p)

    on_cycle = [x != 0 for x in indeg]
    dp = [None] * n

    def make_dp(v):
        res = [1] * m
        for child in children[v]:
            if on_cycle[child]:
                continue
            child_dp = dp[child]
            prefix = 0
            for k in range(m):
                prefix = (prefix + child_dp[k]) % MOD
                res[k] = res[k] * prefix % MOD
        return res

    # The removal order puts every non-cycle child before its parent.
    for v in removed_order:
        dp[v] = make_dp(v)
    for v in range(n):
        if on_cycle[v]:
            dp[v] = make_dp(v)

    answer = 1
    seen = [False] * n
    for start in range(n):
        if on_cycle[start] and not seen[start]:
            combined = [1] * m
            v = start
            while not seen[v]:
                seen[v] = True
                values = dp[v]
                for k in range(m):
                    combined[k] = combined[k] * values[k] % MOD
                v = parent[v]
            answer = answer * (sum(combined) % MOD) % MOD

    print(answer)

if __name__ == "__main__":
    solve()

