import sys
MOD=998244353

def factorize(x):
    out=[]
    d=2
    while d*d<=x:
        if x%d==0:
            e=0
            while x%d==0:
                x//=d; e+=1
            out.append((d,e))
        d+=1
    if x>1: out.append((x,1))
    return out

def contribution(p, exps):
    dp={0:1}
    count=1
    for e in exps:
        nd={}
        if e==0:
            for d,v in dp.items():
                nd[d]=v*pow(p,d,MOD)%MOD
        else:
            for d,v in dp.items():
                x=d+e
                nd[x]=(nd.get(x,0)+v*pow(p,x,MOD))%MOD
                if d>=e:
                    x=d-e
                    w=v*pow(p,x,MOD)%MOD
                else:
                    x=0
                    w=v*pow(p,(e-d)*count,MOD)%MOD
                nd[x]=(nd.get(x,0)+w)%MOD
        dp=nd
        count+=1
    return sum(dp.values())%MOD

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]; a=data[1:]
    primes=set()
    for x in a:
        primes.update(p for p,e in factorize(x))
    ans=1
    for p in primes:
        exps=[]
        for x in a:
            e=0
            while x%p==0:
                x//=p; e+=1
            exps.append(e)
        ans=ans*contribution(p,exps)%MOD
    print(ans)
main()

