import sys, math
MOD=998244353

def factors(x):
 r=[]; d=2
 while d*d<=x:
  if x%d==0:
   e=0
   while x%d==0:x//=d;e+=1
   r.append((d,e))
  d+=1
 if x>1:r.append((x,1))
 return r

def calc(p, es, n):
 dp={0:1}; cnt=1
 for e in es:
  if e==0:
   cnt+=1; continue
  nd={}
  for d,v in dp.items():
   # up
   x=d+e; w=v*pow(p,x,MOD)%MOD
   nd[x]=(nd.get(x,0)+w)%MOD
   # down
   if d>=e: x=d-e; w=v*pow(p,x,MOD)%MOD
   else: x=0; w=v*pow(p,(e-d)*cnt,MOD)%MOD
   nd[x]=(nd.get(x,0)+w)%MOD
  dp=nd;cnt+=1
 return sum(dp.values())%MOD

def main():
