from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # A pair (a,b), with a < b, affects subarrays whose right endpoint
        # is at least b: their left endpoint must be greater than a.
        ending = [[] for _ in range(n + 1)]
        for idx, (x, y) in enumerate(conflictingPairs):
            a, b = (x, y) if x < y else (y, x)
            ending[b].append((a, idx))

        # Among all pairs activated so far, retain the two largest a values.
        # The second one is enough to determine the effect of removing the
        # pair currently supplying the largest value.
        best = (0, -1)
        second = (0, -1)
        baseline = 0
        gains = [0] * len(conflictingPairs)

        for right in range(1, n + 1):
            for a, idx in ending[right]:
                if a > best[0]:
                    second, best = best, (a, idx)
                elif a > second[0]:
                    second = (a, idx)

            baseline += right - best[0]
            if best[1] != -1:
                gains[best[1]] += best[0] - second[0]

        return baseline + max(gains)

