import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    a = data[2:]
    machines = [tuple(a[4*i:4*i+4]) for i in range(n)]

    def feasible(cap):
        total = 0
        for A, P, B, Q in machines:
            max_s = (cap + A - 1) // A
            best = 10**30
            # For each residue of the number of S machines modulo B,
            # the cost is linear between these endpoint ranges.
            for x in range(min(B, max_s + 1)):
                rem = cap - A * x
                cost = x * P + (0 if rem <= 0 else (rem + B - 1) // B * Q)
                if cost < best:
                    best = cost
            for x in range(max(0, max_s - B), max_s + 1):
                rem = cap - A * x
                cost = x * P + (0 if rem <= 0 else (rem + B - 1) // B * Q)
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                return False
        return True

    high = max(max(budget * A // P, budget * B // Q)
               for A, P, B, Q in machines) + 1
    low = 0
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

