MOD = 10**9 + 7

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        length = len(s)

        fact = [1] * (length + 1)
        for i in range(1, length + 1):
            fact[i] = fact[i - 1] * i % MOD
        inv_fact = [1] * (length + 1)
        inv_fact[length] = pow(fact[length], MOD - 2, MOD)
        for i in range(length, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        def choose(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

        # If x has c set bits, its first operation produces c.
        # Thus c must reach 1 in at most k-1 further operations.
        valid_counts = []
        for c in range(1, length + 1):
            value = c
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            if steps <= k - 1:
                valid_counts.append(c)

        answer = 0
        used = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                # Make this bit zero; the suffix can then be arbitrary with
                # the required number of set bits.
                for c in valid_counts:
                    needed = c - used
                    if 0 <= needed <= remaining:
                        answer = (answer + choose(remaining, needed)) % MOD
                used += 1

        return answer

