import heapq


def main():
    input = sys.stdin.readline
    n = int(input())
    rows = [input().strip() for _ in range(n)]

    out = [[[] for _ in range(26)] for _ in range(n)]
    inc = [[[] for _ in range(26)] for _ in range(n)]
    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    heap = []

    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))
        row = rows[i]
        for j, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - ord('a')
                out[i][c].append(j)
                inc[j][c].append(i)
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    heapq.heappush(heap, (1, i, j))

    while heap:
        cur, u, v = heapq.heappop(heap)
        if dist[u][v] != cur:
            continue
        nd = cur + 2
        for c in range(26):
            left = inc[u][c]
            right = out[v][c]
            if not left or not right:
                continue
            for a in left:
                row = dist[a]
                for b in right:
                    if row[b] > nd:
                        row[b] = nd
                        heapq.heappush(heap, (nd, a, b))

    for row in dist:
        print(*(x if x < inf else -1 for x in row))


