import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    pos = 2
    for _ in range(m):
        u, v = data[pos] - 1, data[pos + 1] - 1
        pos += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    pivots = []
    rank = 0
    for col in range(n):
        pivot = next((i for i in range(rank, n)
                      if (rows[i] >> col) & 1), None)
        if pivot is None:
            continue
        rows[rank], rows[pivot] = rows[pivot], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    null_basis = []
    for free in range(n):
        if free in pivot_set:
            continue
        vector = 1 << free
        for i, col in enumerate(pivots):
            if (rows[i] >> free) & 1:
                vector |= 1 << col
        null_basis.append(vector)

    values = [0] * n
    for bit, vector in enumerate(null_basis):
        for vertex in range(n):
            if (vector >> vertex) & 1:
                values[vertex] |= 1 << bit

    if any(value == 0 for value in values):
        print("No")
        return

    limit = (1 << 60) - 1
    largest = max(values)
    if m == 0:
        multiplier = 1
    elif largest * 4 <= limit:
        multiplier = 4
    elif largest * 2 <= limit:
        multiplier = 2
    else:
        multiplier = 1
    print("Yes")
    print(*(value * multiplier for value in values))

