from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        # Number of completions when the next element must have parity req.
        def ways(odd, even, req):
            length = odd + even
            if req == 1:
                if odd != (length + 1) // 2 or even != length // 2:
                    return 0
            else:
                if even != (length + 1) // 2 or odd != length // 2:
                    return 0
            return fact[odd] * fact[even]

        odd = (n + 1) // 2
        even = n // 2
        total = (odd * ways(odd - 1, even, 0) +
                 even * ways(odd, even - 1, 1))
        if k > total:
            return []

        used = [False] * (n + 1)
        answer = []
        previous_parity = None

        for _ in range(n):
            for value in range(1, n + 1):
                parity = value & 1
                if used[value] or (previous_parity is not None and
                                   parity == previous_parity):
                    continue
                new_odd = odd - (parity == 1)
                new_even = even - (parity == 0)
                count = ways(new_odd, new_even, 1 - parity)
                if k > count:
                    k -= count
                else:
                    answer.append(value)
                    used[value] = True
                    odd, even = new_odd, new_even
                    previous_parity = parity
                    break

        return answer

