from typing import List
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact=[1]*(n+1)
        for i in range(1,n+1): fact[i]=fact[i-1]*i
        def ways(o,e,req):
            L=o+e
            if req==1:
                if o!=(L+1)//2 or e!=L//2: return 0
            else:
                if e!=(L+1)//2 or o!=L//2: return 0
            return fact[o]*fact[e]
        o=(n+1)//2; e=n//2
        total=ways(o-1,e,0)+ways(o,e-1,1)
        if k>total: return []
        used=[False]*(n+1); ans=[]; prev=None
        for pos in range(n):
            for x in range(1,n+1):
                if used[x] or (prev is not None and x%2==prev): continue
                no=o-(x%2==1); ne=e-(x%2==0)
                req=1-(x%2)
                cnt=ways(no,ne,req)
                if k>cnt: k-=cnt
                else:
                    ans.append(x); used[x]=True; o,e=no,ne; prev=x%2; break
        return ans

