class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        p = [0] * n
        p[0] = 1 % k
        for i in range(1, n):
            p[i] = p[i - 1] * 10 % k

        half = (n + 1) // 2
        coeff = [0] * half
        for i in range(half):
            j = n - 1 - i
            if i == j:
                coeff[i] = p[i]
            else:
                coeff[i] = (p[i] + p[j]) % k

        # Bit mask of residues reachable by a suffix of the half-digits.
        transitions = [[0] * (1 << k) for _ in range(k)]
        for c in range(k):
            for mask in range(1 << k):
                result = 0
                for digit in range(10):
                    for residue in range(k):
                        if mask & (1 << residue):
                            result |= 1 << ((residue + digit * c) % k)
                transitions[c][mask] = result

        suffix = [0] * (half + 1)
        suffix[half] = 1  # residue 0 with no remaining digits
        for i in range(half - 1, -1, -1):
            suffix[i] = transitions[coeff[i]][suffix[i + 1]]

        remainder = 0
        left = []
        for i, c in enumerate(coeff):
            minimum = 1 if i == 0 else 0
            for digit in range(9, minimum - 1, -1):
                needed = (-remainder - digit * c) % k
                if suffix[i + 1] & (1 << needed):
                    left.append(str(digit))
                    remainder = (remainder + digit * c) % k
                    break

        prefix = ''.join(left)
        mirror = prefix[:-1] if n % 2 else prefix
        return prefix + mirror[::-1]

