    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n=len(nums)
        ng=[n]*n
        st=[]
        for i,x in enumerate(nums):
            while st and nums[st[-1]]<x:
                ng[st.pop()]=i
            st.append(i)
        from array import array
        LOG=n.bit_length()
        ups=[array('i',ng)]
        sm=[array('q',(nums[i]*(ng[i]-i) for i in range(n)))]
        for j in range(1,LOG):
            pu=ups[-1]; ps=sm[-1]
            u=array('i',[0])*n; s=array('q',[0])*n
            for i in range(n):
                m=pu[i]
                u[i]=pu[m] if m<n else n
                s[i]=ps[i]+(ps[m] if m<n else 0)
            ups.append(u); sm.append(s)
        pref=[0]
        for x in nums: pref.append(pref[-1]+x)
        def cost(l,r):
            cur=l; mxsum=0
            for j in range(LOG-1,-1,-1):
                nxt=ups[j][cur]
                if nxt<=r:
                    mxsum+=sm[j][cur]; cur=nxt
            mxsum+=nums[cur]*(r-cur+1)
            return mxsum-(pref[r+1]-pref[l])
        ans=0
        for r in range(n):
            lo=0; hi=r
            while lo<hi:
                mid=(lo+hi)//2
                if cost(mid,r)<=k: hi=mid
                else: lo=mid+1
            ans+=r-lo+1
        return ans

