import sys
from functools import cmp_to_key

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [tuple(data[i:i+2]) for i in range(2, 2 + 2*n, 2)]

    # Process functions from innermost to outermost.  The optimal order for
    # chosen functions is decreasing B/(A-1), with A=1 treated as infinity.
    def compare(x, y):
        a, b = x
        c, d = y
        if a == 1:
            return 0 if c == 1 else -1
        if c == 1:
            return 1
        cross = b * (c - 1) - d * (a - 1)
        if cross > 0:
            return -1
        if cross < 0:
            return 1
        return 0

    funcs.sort(key=cmp_to_key(compare))

    neg = -10**100
    dp = [neg] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for used in range(k, 0, -1):
            if dp[used - 1] != neg:
                dp[used] = max(dp[used], a * dp[used - 1] + b)
    print(dp[k])

if __name__ == '__main__':
    main()

