import sys
from functools import lru_cache

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, l = data[:3]
    values = data[3:]
    total = n + m + l
    takahashi = (1 << n) - 1
    aoki = ((1 << m) - 1) << n
    all_cards = (1 << total) - 1

    lower = []
    for i, x in enumerate(values):
        mask = 0
        for j, y in enumerate(values):
            if y < x:
                mask |= 1 << j
        lower.append(mask)

    @lru_cache(maxsize=None)
    def winning(takahashi_hand, aoki_hand, turn):
        hand = takahashi_hand if turn == 0 else aoki_hand
        if hand == 0:
            return False
        other = aoki_hand if turn == 0 else takahashi_hand
        table = all_cards ^ (takahashi_hand | aoki_hand)

        remaining = hand
        while remaining:
            card = remaining & -remaining
            remaining -= card
            index = card.bit_length() - 1
            hand_after_play = hand ^ card
            table_after_play = table | card

            # The player may choose not to take a card.
            if turn == 0:
                nx, ny = hand_after_play, other
            else:
                nx, ny = other, hand_after_play
            if not winning(nx, ny, 1 - turn):
                return True

            # Try every card that can be taken.
            candidates = table_after_play & lower[index]
            while candidates:
                taken = candidates & -candidates
                candidates -= taken
                new_hand = hand_after_play | taken
                if turn == 0:
                    nx, ny = new_hand, other
                else:
                    nx, ny = other, new_hand
                if not winning(nx, ny, 1 - turn):
                    return True
        return False

    print("Takahashi" if winning(takahashi, aoki, 0) else "Aoki")

if __name__ == "__main__":
    main()

