from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first, middle, last = p.split('*')
        n = len(s)

        def occurrences(pattern):
            if not pattern:
                return list(range(n + 1))
            m = len(pattern)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = prefix[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                prefix[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = prefix[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = prefix[j - 1]
            return result

        starts_first = occurrences(first)
        starts_middle = occurrences(middle)
        starts_last = occurrences(last)

        answer = n + 1
        for start in starts_first:
            pos = bisect_left(starts_middle, start + len(first))
            if pos == len(starts_middle):
                continue
            middle_start = starts_middle[pos]
            pos = bisect_left(starts_last, middle_start + len(middle))
            if pos == len(starts_last):
                continue
            end_start = starts_last[pos]
            answer = min(answer, end_start + len(last) - start)

        return -1 if answer == n + 1 else answer

