def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    pos = 2
    for _ in range(m):
        x, y, z = data[pos] - 1, data[pos + 1] - 1, data[pos + 2]
        pos += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    potential = [None] * n
    answer = [0] * n

    for start in range(n):
        if potential[start] is not None:
            continue
        potential[start] = 0
        component = [start]
        stack = [start]
        while stack:
            v = stack.pop()
            for u, z in graph[v]:
                value = potential[v] ^ z
                if potential[u] is None:
                    potential[u] = value
                    component.append(u)
                    stack.append(u)
                elif potential[u] != value:
                    print(-1)
                    return

        chosen = 0
        size = len(component)
        for bit in range(31):
            ones = 0
            mask = 1 << bit
            for v in component:
                if potential[v] & mask:
                    ones += 1
            if ones * 2 > size:
                chosen |= mask
        for v in component:
            answer[v] = potential[v] ^ chosen

    print(*answer)

