class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        # pa/pb are the best totals ending at the previous hour with A/B.
        # pa2/pb2 are the corresponding totals two hours back.
        pa2 = pb2 = 0
        pa, pb = energyDrinkA[0], energyDrinkB[0]

        for i in range(1, len(energyDrinkA)):
            # To change from B to A, hour i-1 must be the cleansing hour;
            # hence the preceding consumed B hour is i-2 (and vice versa).
            best_a = energyDrinkA[i] + max(pa, pb2 if i >= 2 else 0)
            best_b = energyDrinkB[i] + max(pb, pa2 if i >= 2 else 0)
            pa2, pb2, pa, pb = pa, pb, best_a, best_b

        return max(pa, pb)

