class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def reachable(x: int) -> set:
            s = str(x)
            result = {x}
            digits = list(s)
            for i in range(len(digits)):
                for j in range(i + 1, len(digits)):
                    if digits[i] == digits[j]:
                        continue
                    swapped = digits[:]
                    swapped[i], swapped[j] = swapped[j], swapped[i]
                    result.add(int(''.join(swapped)))
            return result

        all_reachable = [reachable(x) for x in nums]
        answer = 0
        for i in range(len(nums)):
            for j in range(i):
                # At most one number may be changed, so one original must
                # be reachable from the other.
                if nums[i] in all_reachable[j] or nums[j] in all_reachable[i]:
                    answer += 1
        return answer

