class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        # The numbers have at most four digits, so a small sieve is enough.
        limit = 10000
        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, 100):
            if is_prime[p]:
                for q in range(p * p, limit, p):
                    is_prime[q] = False

        if is_prime[n] or is_prime[m]:
            return -1
        if n == m:
            return n

        width = len(str(n))
        place = [10 ** i for i in range(width)]
        infinity = 10 ** 18
        dist = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist.get(value):
                continue
            if value == m:
                return cost

            for pos, p in enumerate(place):
                old = (value // p) % 10
                for new in (old - 1, old + 1):
                    if not (0 <= new <= 9):
                        continue
                    # A leading zero would no longer be a number of the
                    # required digit length.
                    if pos == width - 1 and new == 0:
                        continue
                    nxt = value + (new - old) * p
                    if is_prime[nxt]:
                        continue
                    new_cost = cost + nxt
                    if new_cost < dist.get(nxt, infinity):
                        dist[nxt] = new_cost
                        heapq.heappush(heap, (new_cost, nxt))

        return -1

