class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        ans = 0
        for i in range(1, (n - 1) // 2 + 1):
            if z[i] >= i:
                ans += n - 2 * i

        for d in range(1, n // 2 + 1):
            lcp = [0] * n
            for i in range(n - d - 1, -1, -1):
                if nums[i] == nums[i + d]:
                    v = (lcp[i + 1] + 1) if i + 1 < n else 1
                    lcp[i] = min(d, v)
            for i in range(1, n - 2 * d + 1):
                if lcp[i] >= d:
                    ans += 1
                    if i <= d and z[i] >= i:
                        ans -= 1
        return ans

