class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # A reachability path for every node can be reduced to one outgoing
        # edge per node, so the outgoing-degree bound is automatically met.
        reverse = [[] for _ in range(n)]
        weights = set()
        for a, b, w in edges:
            reverse[b].append((a, w))
            weights.add(w)

        candidates = sorted(weights)

        def possible(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            reached = 1
            while stack:
                v = stack.pop()
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        reached += 1
                        stack.append(u)
            return reached == n

        if not possible(candidates[-1]):
            return -1

        lo, hi = 0, len(candidates) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if possible(candidates[mid]):
                hi = mid
            else:
                lo = mid + 1
        return candidates[lo]

