                    j=mp[ch]; cnt[j]+=1; last[j]=r
                else: cons += 1
                while cons > K:
                    x=word[left]
                    if x in v:
                        cnt[mp[x]]-=1
                    else: cons-=1
                    left+=1
                if min(last) >= left:
                    ans += min(last)-left+1
            return ans
        return atmost(k)-atmost(k-1)

