class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        index = {'a': 0, 'e': 1, 'i': 2, 'o': 3, 'u': 4}

        def at_most(limit: int) -> int:
            if limit < 0:
                return 0
            left = 0
            consonants = 0
            last = [-1] * 5
            result = 0

            for right, ch in enumerate(word):
                vowel_index = index.get(ch, -1)
                if vowel_index >= 0:
                    last[vowel_index] = right
                else:
                    consonants += 1

                while consonants > limit:
                    removed = word[left]
                    if index.get(removed, -1) < 0:
                        consonants -= 1
                    left += 1

                earliest_last = min(last)
                if earliest_last >= left:
                    result += earliest_last - left + 1
            return result

        return at_most(k) - at_most(k - 1)

